4	/// Kind of token rate a [`PricingRate`] row applies to.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
6	pub enum TokenRateKind {
7	    Input,
8	    /// Default/short-lived cache write (Anthropic's 5-minute ephemeral tier; the only cache
9	    /// write tier for providers that don't publish a separate long-lived rate).
10	    CacheWrite,
