19	/// A single versioned pricing row: the rate for one (model, tier, kind) combination,
20	/// valid over an [effective_from, effective_until) window.
21	#[derive(Debug, Clone, PartialEq)]
22	pub struct PricingRate {
23	    pub model: CompactString,
24	    pub tier: Option<CompactString>,
25	    pub kind: TokenRateKind,
26	    pub rate_per_m: f64,
27	    pub effective_from: DateTime<Utc>,
28	    pub effective_until: Option<DateTime<Utc>>,
29	}
