558	        input_tokens: 1_000_000,
559	        output_tokens: 1_000_000,
560	        cache_creation_tokens: 0,
561	        cache_read_tokens: 0,
562	        reasoning_tokens: 500_000,
563	        cache_creation_1h_tokens: 0,
564	    };
