246	/// Maps a real OpenCode tool name (confirmed against real data: `read`, `glob`, `task`, `grep`,
247	/// `bash`; others inferred by the same naming convention) to a `ToolIntent`.
248	fn classify_tool_intent(tool_name: &str, input: &serde_json::Value) -> ToolIntent {
249	    match tool_name {
250	        "read" => {
251	            let path = input.get("filePath").and_then(|v| v.as_str()).unwrap_or("");
252	            ToolIntent::FileRead { path: CompactString::new(path), line_range: None }
253	        }
254	        "write" => {
255	            let path = input.get("filePath").and_then(|v| v.as_str()).unwrap_or("");
256	            ToolIntent::FileCreate { path: CompactString::new(path) }
257	        }
258	        "edit" => {
259	            let path = input.get("filePath").and_then(|v| v.as_str()).unwrap_or("");
260	            ToolIntent::FileEdit { path: CompactString::new(path), lines_added: 0, lines_removed: 0 }
261	        }
262	        "grep" => {
263	            let query = input.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
264	            ToolIntent::CodeSearch { tool: CompactString::new("grep"), query: CompactString::new(query), is_ast: false }
265	        }
266	        "glob" => {
267	            let pattern = input.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
268	            ToolIntent::FileDiscovery { tool: CompactString::new("glob"), pattern: CompactString::new(pattern) }
269	        }
270	        "bash" => {
271	            let cmd = input.get("command").and_then(|v| v.as_str()).unwrap_or("");
272	            if cmd.trim_start().starts_with("git") {
273	                ToolIntent::VersionControl { action: CompactString::new(cmd) }
274	            } else {
275	                ToolIntent::Other { raw_name: CompactString::new("bash") }
276	            }
277	        }
278	        "task" => {
279	            let description = input.get("description").and_then(|v| v.as_str()).unwrap_or("");
280	            ToolIntent::SubagentSpawn {
281	                agent_type: CompactString::new("task"),
282	                description: CompactString::new(description),
283	            }
284	        }
285	        other => ToolIntent::Other { raw_name: CompactString::new(other) },
286	    }
287	}
