#[test]
fn test_cost_reflects_is_fully_priced_and_formats_correctly() {
    let pricing = PricingTable::seed();
    let as_of = Utc.with_ymd_and_hms(2026, 8, 21, 0, 0, 0).unwrap();

    let usage = TurnTokenUsage {
        input_tokens: 1_000_000,
