use chrono::{DateTime, Utc};
use compact_str::CompactString;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

use crate::pricing::{PricingTable, TokenRateKind};
use crate::turn::TurnTokenUsage;

/// A cost value that may or may not be genuinely known, pairing the dollar amount with
/// [`TokenEconomics::is_fully_priced`]'s recognition signal at the type level (CRIT-LUMEN-171).
/// The (`f64` total_cost_usd, `bool` is_fully_priced) pair those fields form is still the right
/// representation for computation and storage -- summing costs across turns/sessions and
/// persisting to SQL both need the raw numeric value regardless of pricing status -- but at the
/// point a cost is surfaced to a human (a CLI table, a report), reading `total_cost_usd` alone
/// silently mis-displays an unpriced session as a suspicious-looking `$0.00`. `Cost` makes that
/// mistake a compile error at the display boundary: obtain one via [`TokenEconomics::cost`] and
/// the `Unpriced` case must be handled to get a number out at all.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Cost {
    /// A dollar amount computed from at least one seeded `PricingTable` row.
    Priced(f64),
    /// No seeded pricing matched the model -- the real cost is unknown, not `$0.00`.
    Unpriced,
}

impl Cost {
    /// Formats this cost for display: `$X.XXXX` when priced, or `unpriced_label` verbatim when
    /// not (e.g. `"unknown (model not in pricing table)"`).
    pub fn format_usd(&self, unpriced_label: &str) -> String {
        match self {
            Cost::Priced(v) => format!("${v:.4}"),
            Cost::Unpriced => unpriced_label.to_string(),
        }
    }
}

/// One turn's token usage plus the pricing context (timestamp, tier) needed to price it
/// independently -- required so a session whose turns straddle a price-change boundary (or a
/// service_tier change) is priced correctly on both sides of the boundary.
#[derive(Debug, Clone, PartialEq)]
pub struct TurnPricingInput {
    pub usage: TurnTokenUsage,
    pub timestamp: DateTime<Utc>,
    pub tier: Option<CompactString>,
}

/// Aggregate session token economics and financial savings metrics.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TokenEconomics {
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub cache_creation_tokens: u64,
    pub cache_read_tokens: u64,
    pub ephemeral_5m_tokens: u64,
    pub ephemeral_1h_tokens: u64,
    pub cache_hit_ratio: f32,
    pub total_cost_usd: f64,
    pub provided_cost_usd: Option<f64>,
    pub baseline_cost_no_cache_usd: f64,
    pub net_savings_usd: f64,
    pub efficiency_multiplier: f32,
    pub per_model: HashMap<CompactString, ModelTokenSummary>,
    pub reasoning_output_tokens: u64,
    /// `false` when `model_name` matched no seeded [`PricingTable`] row (see
    /// [`PricingTable::is_recognized`]) -- callers must render cost as an explicit "unknown",
    /// not `$0.00`, in that case. `total_cost_usd`/`net_savings_usd` are still `0.0` for an
    /// unpriced model (every rate lookup returns 0.0), so this flag is the only signal
    /// distinguishing a genuinely free session from an unpriced one.
    pub is_fully_priced: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ModelTokenSummary {
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub cache_creation_tokens: u64,
    pub cache_read_tokens: u64,
    pub reasoning_tokens: u64,
    pub cost_usd: f64,
    pub turns: u64,
    /// See [`TokenEconomics::is_fully_priced`].
    pub is_fully_priced: bool,
}

impl ModelTokenSummary {
    /// See [`TokenEconomics::cost`].
    pub fn cost(&self) -> Cost {
        if self.is_fully_priced {
            Cost::Priced(self.cost_usd)
        } else {
            Cost::Unpriced
        }
    }
}

impl TokenEconomics {
    /// Computes full economic summary from one [`TurnPricingInput`] per turn. Each turn is
    /// priced independently via `pricing.rate_for` at that turn's own timestamp/tier, and the
    /// per-turn costs are summed into `total_cost_usd` -- required so a session whose turns
    /// straddle a price-change boundary is priced correctly on both sides. Token counters
    /// remain simple sums across turns, unaffected by the per-turn pricing. An empty `turns`
    /// slice returns a zeroed `TokenEconomics`, not an error.
    pub fn calculate(
        turns: &[TurnPricingInput],
        model_name: &str,
        pricing: &PricingTable,
        provided_cost_usd: Option<f64>,
    ) -> Self {
        let is_fully_priced = pricing.is_recognized(model_name);

        let mut input_tokens = 0u64;
        let mut output_tokens = 0u64;
        let mut cache_creation_tokens = 0u64;
        let mut cache_creation_1h_tokens = 0u64;
        let mut cache_read_tokens = 0u64;
        let mut reasoning_tokens_total = 0u64;
        let mut total_cost_usd = 0.0f64;
        let mut baseline_cost_no_cache_usd = 0.0f64;

        for turn in turns {
            let usage = &turn.usage;
            let tier = turn.tier.as_deref();

            let input_rate = pricing.rate_for(model_name, tier, TokenRateKind::Input, turn.timestamp);
            let cache_write_5m_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheWrite, turn.timestamp);
            let cache_write_1h_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheWrite1h, turn.timestamp);
            let cache_read_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheRead, turn.timestamp);
            let output_rate = pricing.rate_for(model_name, tier, TokenRateKind::Output, turn.timestamp);
            let reasoning_rate = pricing.rate_for(model_name, tier, TokenRateKind::Reasoning, turn.timestamp);

            let cache_write_5m_tokens = usage.cache_creation_tokens.saturating_sub(usage.cache_creation_1h_tokens);

            let turn_cost = (usage.input_tokens as f64 / 1_000_000.0) * input_rate
                + (cache_write_5m_tokens as f64 / 1_000_000.0) * cache_write_5m_rate
                + (usage.cache_creation_1h_tokens as f64 / 1_000_000.0) * cache_write_1h_rate
                + (usage.cache_read_tokens as f64 / 1_000_000.0) * cache_read_rate
                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate
                + (usage.reasoning_tokens as f64 / 1_000_000.0) * reasoning_rate;

            // Reasoning tokens are priced at the same rate in both the actual and no-cache
            // baseline cost -- caching doesn't apply to reasoning tokens, so omitting this term
            // from one side but not the other would skew net_savings_usd/efficiency_multiplier.
            let turn_baseline_cost = (usage.prompt_tokens() as f64 / 1_000_000.0) * input_rate
                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate
                + (usage.reasoning_tokens as f64 / 1_000_000.0) * reasoning_rate;

            input_tokens += usage.input_tokens;
            output_tokens += usage.output_tokens;
            cache_creation_tokens += usage.cache_creation_tokens;
            cache_creation_1h_tokens += usage.cache_creation_1h_tokens;
            cache_read_tokens += usage.cache_read_tokens;
            reasoning_tokens_total += usage.reasoning_tokens;
            total_cost_usd += turn_cost;
            baseline_cost_no_cache_usd += turn_baseline_cost;
        }

        let prompt_total = input_tokens + cache_creation_tokens + cache_read_tokens;
        let cache_hit_ratio =
            if prompt_total > 0 { (cache_read_tokens as f32 / prompt_total as f32) * 100.0 } else { 0.0 };

        let net_savings_usd = (baseline_cost_no_cache_usd - total_cost_usd).max(0.0);

        let efficiency_multiplier =
            if total_cost_usd > 0.0 { (baseline_cost_no_cache_usd / total_cost_usd) as f32 } else { 1.0 };

        let mut per_model = HashMap::new();
        if !turns.is_empty() {
            per_model.insert(
                CompactString::new(model_name),
                ModelTokenSummary {
                    input_tokens,
                    output_tokens,
                    cache_creation_tokens,
                    cache_read_tokens,
                    reasoning_tokens: reasoning_tokens_total,
                    cost_usd: total_cost_usd,
                    turns: turns.len() as u64,
                    is_fully_priced,
                },
            );
        }

        Self {
            input_tokens,
            output_tokens,
            cache_creation_tokens,
            cache_read_tokens,
            ephemeral_5m_tokens: cache_creation_tokens.saturating_sub(cache_creation_1h_tokens),
            ephemeral_1h_tokens: cache_creation_1h_tokens,
            cache_hit_ratio,
            total_cost_usd,
            provided_cost_usd,
            baseline_cost_no_cache_usd,
            net_savings_usd,
            efficiency_multiplier,
            per_model,
            reasoning_output_tokens: reasoning_tokens_total,
            is_fully_priced,
        }
    }

    /// Surfaces `total_cost_usd`/`is_fully_priced` as a single [`Cost`] value -- the
    /// CRIT-LUMEN-171 display-boundary accessor. Prefer this over reading `total_cost_usd`
    /// directly whenever the value is headed somewhere a human will read it.
    pub fn cost(&self) -> Cost {
        if self.is_fully_priced {
            Cost::Priced(self.total_cost_usd)
        } else {
            Cost::Unpriced
        }
    }
}

        ("claude-3-5-sonnet", 15.00),
        ("claude-3-5-haiku", 4.00),
        ("qwen-2.5-coder", 0.60),
        ("claude-opus", 75.00),
        ("deepseek-r1", 2.19),
        ("kimi-k1.5", 2.00),
        ("glm-4-plus", 1.40),
        ("gemini-2.0-pro", 5.00),
    ] {
        push(model, TokenRateKind::Reasoning, output_rate);
    }

    rates.extend(crate::pricing_source::load_vendored_rates(epoch));

    Self { rates }
}

/// Normalizes a raw, provider-versioned model string (e.g. "claude-3-5-haiku-20241022",
/// "gpt-4o-2024-08-06", "gemini-2.0-flash-001") down to one of this table's seeded
/// canonical keys, by trying progressively shorter '-'-delimited prefixes of `model`
/// against the set of model names actually present in `self.rates`, longest prefix first.
/// Returns `None` when no prefix matches any seeded key -- callers must fall back to the
/// CRIT-LUMEN-008 unrecognized-model behavior in that case.
///
/// A small explicit alias table was considered instead, but seeded keys are themselves
/// hyphen-delimited words (e.g. "claude-3-5-haiku") and every real-world date/version
/// suffix observed (YYYYMMDD, YYYY-MM-DD, "-001", "-exp", "-32b-instruct") is just extra
/// hyphen-delimited segments appended after the canonical name. Prefix-shortening solves
/// all of them with one algorithm and needs no maintenance as new dated releases appear,
/// whereas an alias table would need a new entry per new version string.
fn normalize_model_key<'a>(&'a self, model: &'a str) -> Option<&'a str> {
    let parts: Vec<&str> = model.split('-').collect();
    for end in (1..=parts.len()).rev() {
        // Only accept this (shorter) candidate if every segment it would strip from the
        // tail is a safe version/date/scale marker -- never a segment that could denote a
        // genuinely different, differently-priced model (e.g. "mini", "lite", "nano").
        if !parts[end..].iter().all(|seg| Self::is_safe_strip_segment(seg)) {
            continue;
        }
        let candidate = &model[..Self::prefix_byte_len(&parts, end)];
        if self.rates.iter().any(|r| r.model == candidate) {
            return Some(candidate);
        }
    }
    None
}

/// Whether a single '-'-delimited segment stripped from the tail of a raw model string is
/// safe to discard when normalizing -- i.e. it can only ever denote a version, release
/// date, or parameter-scale marker, never a genuinely different priced model name.
///
/// Deliberately an ALLOWLIST of safe-to-strip patterns, not a denylist of known-bad words:
/// a denylist can never be complete (new differently-priced model tiers are named
/// constantly -- "mini", "nano", "flash-lite", ...), whereas the set of ways providers
/// encode version/date/scale is small and closed.
///
/// 1. Numeric-only segments ("20241022", "001", "0528", "4", "1") -- a bare number is never
///    a model-tier name.
/// 2. Parameter-scale segments matching `^\d+[A-Za-z]$` ("32b", "70b") -- digits followed by
///    exactly one trailing letter denote model SIZE within the same family/price tier, not
///    a different-tier product name. Deliberately the strict single-trailing-letter form,
///    not a looser pattern that would also admit multi-token scale strings like "8x7b" --
///    no seeded key requires stripping that shape, so the stricter (safer) form is kept.
/// 3. A small explicit allowlist of known non-differentiating tuning-suffix words.
fn is_safe_strip_segment(segment: &str) -> bool {
    if !segment.is_empty() && segment.chars().all(|c| c.is_ascii_digit()) {
        return true;
    }

    if let Some(last) = segment.chars().next_back() {
        if last.is_ascii_alphabetic() {
            let digits = &segment[..segment.len() - last.len_utf8()];
            if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
                return true;
            }
        }
    }

    // "fast"/"high" cover real observed request-time speed/effort variant suffixes
    // (gpt-5.6-terra-fast, gemini-3.7-flash-high) that carry no separately published price
    // for their provider. This is a deliberate, narrower judgment call than the rest of this
    // allowlist: Anthropic's "fast mode" IS a genuinely different, separately published
    // 2x-priced product (confirmed on platform.claude.com/docs/en/about-claude/pricing) --
    // but it is applied via a request parameter (`speed: "fast"`), never observed embedded
    // in a real `message.model` string this session. If a provider ever starts encoding
    // "-fast"/"-high" as part of the model name string for a genuinely different-priced
    // tier, this allowlist entry would silently mis-price it -- revisit if that's observed.
    matches!(segment, "exp" | "latest" | "preview" | "instruct" | "chat" | "fast" | "high")
}

/// Byte length of the '-'-joined prefix consisting of the first `count` elements of
/// `parts` (which were produced by splitting the original string on '-').
fn prefix_byte_len(parts: &[&str], count: usize) -> usize {
    let joined_len: usize = parts[..count].iter().map(|p| p.len()).sum();
    // account for the (count - 1) '-' separators between the included parts
    joined_len + count.saturating_sub(1)
}

/// Whether `model` -- after normalizing away any provider-versioning suffix -- matches at
/// least one seeded row. Callers use this to distinguish "priced at 0.0 because this model
/// genuinely has no cost for this token kind" from "priced at 0.0 because this model has no
/// seeded pricing at all" (an unrecognized model), the latter of which must be surfaced to
