9	/// A cost value that may or may not be genuinely known, pairing the dollar amount with
10	/// [`TokenEconomics::is_fully_priced`]'s recognition signal at the type level (CRIT-LUMEN-171).
11	/// The (`f64` total_cost_usd, `bool` is_fully_priced) pair those fields form is still the right
12	/// representation for computation and storage -- summing costs across turns/sessions and
13	/// persisting to SQL both need the raw numeric value regardless of pricing status -- but at the
14	/// point a cost is surfaced to a human (a CLI table, a report), reading `total_cost_usd` alone
15	/// silently mis-displays an unpriced session as a suspicious-looking `$0.00`. `Cost` makes that
16	/// mistake a compile error at the display boundary: obtain one via [`TokenEconomics::cost`] and
17	/// the `Unpriced` case must be handled to get a number out at all.
18	#[derive(Debug, Clone, Copy, PartialEq)]
19	pub enum Cost {
20	    /// A dollar amount computed from at least one seeded `PricingTable` row.
21	    Priced(f64),
22	    /// No seeded pricing matched the model -- the real cost is unknown, not `$0.00`.
23	    Unpriced,
24	}
25	
26	impl Cost {
27	    /// Formats this cost for display: `$X.XXXX` when priced, or `unpriced_label` verbatim when
28	    /// not (e.g. `"unknown (model not in pricing table)"`).
29	    pub fn format_usd(&self, unpriced_label: &str) -> String {
30	        match self {
31	            Cost::Priced(v) => format!("${v:.4}"),
32	            Cost::Unpriced => unpriced_label.to_string(),
33	        }
34	    }
35	}
