85	impl ModelTokenSummary {
86	    /// See [`TokenEconomics::cost`].
87	    pub fn cost(&self) -> Cost {
88	        if self.is_fully_priced {
89	            Cost::Priced(self.cost_usd)
90	        } else {
91	            Cost::Unpriced
92	        }
93	    }
94	}
