96	impl TokenEconomics {
97	    /// Computes full economic summary from one [`TurnPricingInput`] per turn. Each turn is
98	    /// priced independently via `pricing.rate_for` at that turn's own timestamp/tier, and the
99	    /// per-turn costs are summed into `total_cost_usd` -- required so a session whose turns
100	    /// straddle a price-change boundary is priced correctly on both sides. Token counters
101	    /// remain simple sums across turns, unaffected by the per-turn pricing. An empty `turns`
102	    /// slice returns a zeroed `TokenEconomics`, not an error.
103	    pub fn calculate(
104	        turns: &[TurnPricingInput],
105	        model_name: &str,
106	        pricing: &PricingTable,
107	        provided_cost_usd: Option<f64>,
108	    ) -> Self {
109	        let is_fully_priced = pricing.is_recognized(model_name);
110	        // Narrows the (now ~1,500+ row, post-CRIT-LUMEN-170) pricing table down to this model's
111	        // rows once, outside the loop below, instead of re-scanning the full table on every one
112	        // of the 6 rate_for calls per turn.
113	        let rows = pricing.rows_for_model(model_name);
114	
115	        let mut input_tokens = 0u64;
116	        let mut output_tokens = 0u64;
117	        let mut cache_creation_tokens = 0u64;
118	        let mut cache_creation_1h_tokens = 0u64;
119	        let mut cache_read_tokens = 0u64;
120	        let mut reasoning_tokens_total = 0u64;
121	        let mut total_cost_usd = 0.0f64;
122	        let mut baseline_cost_no_cache_usd = 0.0f64;
123	
124	        for turn in turns {
125	            let usage = &turn.usage;
126	            let tier = turn.tier.as_deref();
127	
128	            let input_rate = PricingTable::rate_for_rows(&rows, tier, TokenRateKind::Input, turn.timestamp);
129	            let cache_write_5m_rate =
130	                PricingTable::rate_for_rows(&rows, tier, TokenRateKind::CacheWrite, turn.timestamp);
131	            let cache_write_1h_rate =
132	                PricingTable::rate_for_rows(&rows, tier, TokenRateKind::CacheWrite1h, turn.timestamp);
133	            let cache_read_rate = PricingTable::rate_for_rows(&rows, tier, TokenRateKind::CacheRead, turn.timestamp);
134	            let output_rate = PricingTable::rate_for_rows(&rows, tier, TokenRateKind::Output, turn.timestamp);
135	            let reasoning_rate = PricingTable::rate_for_rows(&rows, tier, TokenRateKind::Reasoning, turn.timestamp);
136	
137	            let cache_write_5m_tokens = usage.cache_creation_tokens.saturating_sub(usage.cache_creation_1h_tokens);
138	
139	            let turn_cost = (usage.input_tokens as f64 / 1_000_000.0) * input_rate
140	                + (cache_write_5m_tokens as f64 / 1_000_000.0) * cache_write_5m_rate
141	                + (usage.cache_creation_1h_tokens as f64 / 1_000_000.0) * cache_write_1h_rate
142	                + (usage.cache_read_tokens as f64 / 1_000_000.0) * cache_read_rate
143	                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate
144	                + (usage.reasoning_tokens as f64 / 1_000_000.0) * reasoning_rate;
145	
146	            // Reasoning tokens are priced at the same rate in both the actual and no-cache
147	            // baseline cost -- caching doesn't apply to reasoning tokens, so omitting this term
148	            // from one side but not the other would skew net_savings_usd/efficiency_multiplier.
149	            let turn_baseline_cost = (usage.prompt_tokens() as f64 / 1_000_000.0) * input_rate
150	                + (usage.output_tokens as f64 / 1_000_000.0) * output_rate
151	                + (usage.reasoning_tokens as f64 / 1_000_000.0) * reasoning_rate;
152	
153	            input_tokens += usage.input_tokens;
154	            output_tokens += usage.output_tokens;
155	            cache_creation_tokens += usage.cache_creation_tokens;
156	            cache_creation_1h_tokens += usage.cache_creation_1h_tokens;
157	            cache_read_tokens += usage.cache_read_tokens;
158	            reasoning_tokens_total += usage.reasoning_tokens;

