    /// each, ordered by `session.time_created`.
    pub fn parse_database(&self, path: &Path) -> Result<Vec<CanonicalTranscript>, IngestionError> {
        let conn = Connection::open_with_flags(path, OpenFlags::SQLITE_OPEN_READ_ONLY)?;

